class Solution {
    private int dfs(int start, List<Integer> debts) {
        int n = debts.size();
        while (start < n && debts.get(start) == 0) start++;
        if (start == n) return 0;
        int minOps = Integer.MAX_VALUE;
        for (int i = start + 1; i < n; i++) {
            if ((long) debts.get(start) * debts.get(i) < 0) {
                debts.set(i, debts.get(i) + debts.get(start));
                minOps = Math.min(minOps, 1 + dfs(start + 1, debts));
                debts.set(i, debts.get(i) - debts.get(start));
                if (debts.get(start) + debts.get(i) == 0) break;
            }
        }
        return minOps;
    }

    public int minTransfers(int[][] transactions) {
        Map<Integer, Integer> balance = new HashMap<>();
        for (int[] t : transactions) {
            balance.put(t[0], balance.getOrDefault(t[0], 0) - t[2]);
            balance.put(t[1], balance.getOrDefault(t[1], 0) + t[2]);
        }
        List<Integer> debts = new ArrayList<>();
        for (int bal : balance.values()) {
            if (bal != 0) debts.add(bal);
        }
        return dfs(0, debts);
    }
}

var minTransfers = function(transactions) {
    const balance = new Map();
    for (const [u, v, amount] of transactions) {
        balance.set(u, (balance.get(u) || 0) - amount);
        balance.set(v, (balance.get(v) || 0) + amount);
    }
    const debts = [];
    for (const bal of balance.values()) {
        if (bal !== 0) debts.push(bal);
    }
    const n = debts.length;

    function dfs(start) {
        while (start < n && debts[start] === 0) start++;
        if (start === n) return 0;
        let minOps = Infinity;
        for (let i = start + 1; i < n; i++) {
            if (debts[start] * debts[i] < 0) {
                debts[i] += debts[start];
                minOps = Math.min(minOps, 1 + dfs(start + 1));
                debts[i] -= debts[start];
                if (debts[start] + debts[i] === 0) break;
            }
        }
        return minOps;
    }

    return dfs(0);
};
